/// <summary>
/// METCoverNoteDP class.
/// </summary>
[SrsReportParameterAttribute(classStr(METCoverNoteContract))]
public class METCoverNoteDP extends SrsReportDataProviderPreProcessTempDB
{
    METCoverNoteContract            contract;
    METCoverNoteTotesTmp            totesTmp;
    METCoverNoteHeaderTmp           headerTmp;
    METCoverNoteSalesOrdersTmp      salesOrdersTmp;
    METCoverNoteProductTypesTmp     productTypesTmp;
    METCoverNoteTrasnferOrderTmp    transferOrderTmp;


    METBundleGuid   bundleHeaderReportGuid;
    METBundleGuid   headerReportGuid;
    
    Map consolidatedWeightMap               = new Map(Types::String, Types::Real);
    Map consolidatedCasesMap                = new Map(Types::String, Types::Real);
    Map consolidatedBrokenCasesMap          = new Map(Types::String, Types::Real);
    Map consolidatedQuantityOutMap          = new Map(Types::String, Types::Real);
    Map consolidatedProductWeightTotalMap   = new Map(Types::String, Types::Real);

    Set processedShipmentIdsSet             = new Set(Types::String);

    const str containerTypeCodeCHP = 'CHP';
    const str containerTypeCodeLOS = 'LOS';
    const str containerTypeCodeLFT = 'LFT';
    const str containerTypeCodeBLT = 'BLT';
    const str containerTypeCodePLN = 'PLN';
    const str containerTypeCodeTOT = 'TOT';
    const str containerTypeCodeKEG = 'KEG';
    const str containerTypeCodeSEC = 'SEC';
    const str containerTypeCodeREP = 'REP';

}

