// <summary>
/// Set the bundling guid values to the tmp tables
/// </summary>
/// <param name = "_bundleHeaderReportGuid">Bundle header report guid</param>
/// <param name = "_headerReportGuid">Header report guid</param>
public void setBundlingGuid(METBundleGuid     _bundleHeaderReportGuid, METBundleGuid    _headerReportGuid)
{
    bundleHeaderReportGuid = _bundleHeaderReportGuid;
    headerReportGuid = _headerReportGuid;
}

    /// <summary>
    /// Get branding details from industry key
    /// </summary>
    /// <param name = "_industryKey">Industry Key</param>
    /// <returns>SysDocuBrandDetails</returns>
    public SysDocuBrandDetails getDocuBrandDetails(METIndustryKey _industryKey)
    {
        SysDocuBrandDetails docuBrandDetails;

        select firstonly docuBrandDetails
            where docuBrandDetails.ReportName == METConstants::METCoverNoteReport
            && docuBrandDetails.METIndustryKey == _industryKey;

        return docuBrandDetails;
    }

/// <summary>
/// If the item on the sales line has a Product attribute listed in the new setup table, set IsKegItem = Yes
/// </summary>
/// <param name = "_itemId">Item Id</param>
/// <returns><c>boolean</c> object</returns>
protected boolean isKegItem(ItemId    _itemId)
{
    return METCoverNoteDP::itemHasCartonsOrKegs(_itemId);
}

    /// <summary>
    /// Determines whether a given item belongs to a product category
    /// where the CartonsOrKegs flag is enabled.
    /// </summary>
    /// <param name="_itemId">
    /// The ItemId of the product to check.
    /// </param>
    /// <returns>
    /// True if the item is linked to a category with CartonsOrKegs = Yes;
    /// otherwise, false.
    /// </returns>
    public static boolean itemHasCartonsOrKegs(ItemId _itemId)
    {
        EcoResProductCategory   ecoResProductCategory;
        EcoResCategory          ecoResCategory;
        EcoResProduct           ecoResProduct;
        InventTable             inventTable;

        // Select the first matching category for the given item where METCartonsOrKegs = true
        select firstonly ecoResProductCategory
        join ecoResCategory
            where ecoResCategory.RecId == ecoResProductCategory.Category
               && ecoResCategory.METCartonsOrKegs == NoYes::Yes
        join ecoResProduct
            where ecoResProduct.RecId == ecoResProductCategory.Product
        join inventTable
            where inventTable.Product == ecoResProduct.RecId
               && inventTable.ItemId == _itemId;

        return ecoResCategory ? true : false;
    }

    /// <summary>
    /// ProcessReport
    /// </summary>
    public void processReport()
    {
        CustTable                           custTable;
        TMSCarrier                          tmsCarrier;
        SalesTable                          salesTable;
        CompanyInfo                         companyInfo;
        TMSSalesTable                       tmsSalesTable;
        InventLocation                      inventLocation, inventLocationTo;
        METInventLocation                   metInventLocation;
        SysDocuBrandDetails                 docuBrandingDetails;
        METIndustryKeyTable                 industryKeyTable;
        InventTransferTable                 transferTable;
        METInventTransferTableExt           transferTableExt;
        METSalesOrderShipmentLoadLines      shipmentLines;
        METSalesOrderShipmentLoadHeader     shipmentHeader;
        METWarehouseCarrierCustomerView     whsCustomerCarrier;
        METProofOfDocNumber                 docNumSeq;
        
        headerTmp.clear();

        contract = this.parmDataContract();

        //Fetch the record from the <c>METSalesOrderShipmentLoadHeader</c>
        select firstonly CustAccount, ToWarehouse, ToWHInternalCustomer, TransactionType, Warehouse, Route, RouteStopNum, ShipmentId, LoadId, CoverNotesNumSeq, ModifiedBy, CreatedBy from shipmentHeader
            where shipmentHeader.ShipmentId == contract.parmShipmentId();

        if (shipmentHeader.RecId)
        {
            if (shipmentHeader.TransactionType == METOrderTransactionType::SalesOrder)
            {
                this.addCustomerDetails(shipmentHeader.CustAccount, shipmentHeader.Warehouse);
            }
            else if (shipmentHeader.TransactionType == METOrderTransactionType::TransferOrder)
            {
                METSalesOrderShipmentLoadLines shipmentLineOrder;

                select firstonly OrderNum from shipmentLineOrder
                    where shipmentLineOrder.ShipmentId == contract.parmShipmentId();

                if (shipmentLineOrder.OrderNum)
                {
                    METInventTransferTableExt metTransferTableLoc = METInventTransferTableExt::findByTransferId(shipmentLineOrder.OrderNum);
                    this.addCustomerDetails(metTransferTableLoc.InternalCustomer, shipmentHeader.Warehouse);
                }
            }

            select firstonly METDocumentNum, METRevision, METRevisionDate from companyInfo
                where companyInfo.DataArea == curExt();

            //Fetch the Industry key table record using ToWarehouse of <c>METSalesOrderShipmentLoadHeader</c>
            select firstonly RecId, Name, InventLocationId from inventLocation
                where inventLocation.InventLocationId == shipmentHeader.Warehouse
                join CompanyName, IndustryKey from industryKeyTable
                where industryKeyTable.IndustryKey == inventLocation.METWHSubEntity;

            docuBrandingDetails = this.getDocuBrandDetails(industryKeyTable.IndustryKey);

            headerTmp.IndustryKey           = industryKeyTable.IndustryKey;
            headerTmp.CompanyName           = industryKeyTable.CompanyName;

            headerTmp.Carrier               = shipmentHeader.displayShippingCarrier();
            headerTmp.PrimaryImage          = docuBrandingDetails.Image1Name;
            headerTmp.CompanyABN            = docuBrandingDetails.METTaxRegNumber;
            headerTmp.ShipmentId            = shipmentHeader.ShipmentId;
            headerTmp.Revision              = companyInfo.METRevision;
            headerTmp.RevisionDate          = companyInfo.METRevisionDate;
            headerTmp.DocumentNumber        = companyInfo.METDocumentNum;
            headerTmp.Phone                 = docuBrandingDetails.Phone;

            headerTmp.RunNumber             = strFmt("%1/%2", shipmentHeader.Route, shipmentHeader.RouteStopNum);
            headerTmp.ReportDateTime        = DateTimeUtil::getSystemDateTime();
            headerTmp.ReportUser            = XUserInfo::find(false, shipmentHeader.CreatedBy).name;

            headerTmp.WarehouseName         = inventLocation.Name;
            headerTmp.WarehouseAddress      = inventLocation.address();
            headerTmp.OrderNumber           = shipmentLines.OrderNum;

            headerTmp.BundleReportHeaderGuidStr    = bundleHeaderReportGuid;
            headerTmp.CoverNotesHeaderGuidStr      = headerReportGuid;

            this.addContainerTable(shipmentHeader.ShipmentId);
            this.insertLineData(shipmentHeader.ShipmentId, shipmentHeader.TransactionType);

            headerTmp.insert();

            if (shipmentHeader.CoverNotesNumSeq)
            {
                update_recordset headerTmp
                    setting PODNumber = shipmentHeader.CoverNotesNumSeq;
            }
            else
            {
                docNumSeq = METCoverNoteDP::getNumberSeq();

                if (docNumSeq)
                {
                    METSalesOrderShipmentLoadHeader metSalesOrderShipmentLoadHeaderLocal;

                    update_recordset metSalesOrderShipmentLoadHeaderLocal
                        setting CoverNotesNumSeq = docNumSeq
                            where metSalesOrderShipmentLoadHeaderLocal.LoadId == shipmentHeader.LoadId;

                    update_recordset headerTmp
                        setting PODNumber = docNumSeq;
                }
            }
        }
    }

    /// <summary>
    /// Insert line level data.
    /// </summary>
    /// <param name = "_shipmentID">Shipment ID</param>
    public void insertLineData(MetShipmentId _shipmentID, METOrderTransactionType _transactionType)
    {
        Map                             productTypeDescMap = new Map(Types::String, Types::String);
        SalesLine                       salesLine;
        METSalesLine                    metSalesLine;
        InventDim                       inventDim;
        WHSFilters                      whsFilters;
        METItemType                     itemType;
        container                       conProductType;
        InventTransferLine              transferLine;
        METInventTransferLine           metTransferLine;
        METInventItemOrderSetup         metInventItemOrderSetup;
        METSalesOrderShipmentLoadLines  shipmentLines;

        productTypesTmp.clear();
        salesOrdersTmp.clear();
        transferOrderTmp.clear();
        
        while select OrderNum from shipmentLines group by OrderNum
            where shipmentLines.ShipmentId == contract.parmShipmentId()
        {
            headerTmp.OrderNumber = shipmentLines.OrderNum;

            if (_transactionType == METOrderTransactionType::SalesOrder)
            {
                salesOrdersTmp.SalesId                   = shipmentLines.OrderNum;
                salesOrdersTmp.BundleReportHeaderGuidStr = bundleHeaderReportGuid;
                salesOrdersTmp.CoverNotesHeaderGuidStr   = headerReportGuid;
                salesOrdersTmp.insert();

                this.addTotes(shipmentLines.OrderNum);

                salesLine.clear();
                metSalesLine.clear();
                inventDim.clear();
                metInventItemOrderSetup.clear();
                itemType.clear();

                while select salesLine
                    where salesLine.SalesId == shipmentLines.OrderNum
                        && salesLine.SalesStatus != SalesStatus::Canceled
                    join metSalesLine where metSalesLine.SalesLine == salesLine.RecId
                    join inventDim where inventDim.inventDimId == salesLine.InventDimId
                    join ItemType from metInventItemOrderSetup where metInventItemOrderSetup.ItemId == salesLine.ItemId
                    && metInventItemOrderSetup.SiteId == inventDim.InventSiteId
                    join itemType where itemType.ItemType == metInventItemOrderSetup.ItemType
                {
                    if (!productTypeDescMap.exists(metInventItemOrderSetup.ItemType))
                    {
                        productTypeDescMap.insert(metInventItemOrderSetup.ItemType, itemType.Description);
                        conProductType += [metInventItemOrderSetup.ItemType];
                    }
                }

                this.getProductTypesDetailsSO(shipmentLines.OrderNum, contract.parmShipmentId());
            }
            else if (_transactionType == METOrderTransactionType::TransferOrder)
            {
                headerTmp.OrderNumber = shipmentLines.OrderNum;

                transferOrderTmp.TransferId                 = shipmentLines.OrderNum;
                transferOrderTmp.BundleReportHeaderGuidStr  = bundleHeaderReportGuid;
                transferOrderTmp.CoverNotesHeaderGuidStr    = headerReportGuid;
                transferOrderTmp.insert();

                transferLine.clear();
                metTransferLine.clear();
                whsFilters.clear();

                // TO: key by WarehouseCategory — matches consolidatedCasesMap key in getProductTypesDetailsTO.
                // conProductType stores WarehouseCategory — the final loop passes it as _whsCategory.
                while select transferLine where transferLine.TransferId == shipmentLines.OrderNum
                    join metTransferLine where metTransferLine.InventTransferLine == transferLine.RecId
                    join whsFilters where whsFilters.FilterTitle == WHSFilterTitle::Code1
                    && whsFilters.FilterNum   == metTransferLine.WarehouseCategory
                {
                    if (!productTypeDescMap.exists(metTransferLine.WarehouseCategory))
                    {
                        productTypeDescMap.insert(metTransferLine.WarehouseCategory, whsFilters.Description);
                        conProductType += [metTransferLine.WarehouseCategory];
                    }
                }

                this.getProductTypesDetailsTO(shipmentLines.OrderNum, contract.parmShipmentId());
            }
        }

        int i;

        for (i = 1; i <= conLen(conProductType); i++)
        {
            str         valueStr    = conPeek(conProductType, i);
            Description description = productTypeDescMap.lookup(valueStr);

            this.insertProductTypesData(contract.parmShipmentId(), valueStr, description);
        }
    }

    /// <summary>
    /// Insert product type details into tmp table.
    /// </summary>
    /// <param name = "_shipmentId">Shipment id</param>
    /// <param name = "_whsCategory">Warehouse category</param>
    /// <param name = "_productType">Description</param>
    public void insertProductTypesData(MetShipmentId _shipmentId, str _whsCategory, Description _productType)
    {
        METCase         cases               = 0;
        METBrokenCase   brokenCases         = 0;
        METGrossWeight  weight              = 0;
        METGrossWeight  totalProducttWeight = 0;
        METGrossWeight  totalWeight         = 0;
        MapEnumerator   totalProductWeightMapEnumerator;

        totalWeight         = 0;
        totalProducttWeight = 0;

        if (consolidatedCasesMap.exists(_whsCategory))
        {
            cases = consolidatedCasesMap.lookup(_whsCategory);
        }

        if (consolidatedWeightMap.exists(_whsCategory))
        {
            weight = consolidatedWeightMap.lookup(_whsCategory);
        }

        if (consolidatedBrokenCasesMap.exists(_whsCategory))
        {
            brokenCases = consolidatedBrokenCasesMap.lookup(_whsCategory);
        }

        totalProductWeightMapEnumerator = consolidatedWeightMap.getEnumerator();

        while (totalProductWeightMapEnumerator.moveNext())
        {
            totalProducttWeight += totalProductWeightMapEnumerator.currentValue();
        }

        productTypesTmp.clear();
        productTypesTmp.ProductType                 = _productType;
        productTypesTmp.METCase                     = cases;
        productTypesTmp.BrokenCase                  = brokenCases;
        productTypesTmp.GrossWeight                 = weight;
        productTypesTmp.ProductTotalWeight          = totalProducttWeight;

        if (!processedShipmentIdsSet.in(_shipmentId))
        {
            productTypesTmp.PalletContainerTotalWeight  = this.palletContainerWeight(_shipmentId);
        }
        productTypesTmp.TotalWeight                 = productTypesTmp.ProductTotalWeight + productTypesTmp.PalletContainerTotalWeight;

        productTypesTmp.BundleReportHeaderGuidStr   = bundleHeaderReportGuid;
        productTypesTmp.CoverNotesHeaderGuidStr     = headerReportGuid;
    
        productTypesTmp.insert();

    }

    /// <summary>
    /// Add product types for the transfer order.
    /// </summary>
    /// <param name = "_transferId">Transfer order number</param>
    /// <param name = "_shipmentId">Shipment number</param>
    public void getProductTypesDetailsTO(InventTransferId _transferId, MetShipmentId _shipmentId)
    {
        Factor                          factor;
        METCase                         cases, existingCases;
        METUnitWeight                   shippedWeight, existingWeight;
        METBrokenCase                   brokenCases, existingBrokenCases;
        METFilterCodeone                filterCode;
        METLegalEntityType              legalEntityType = CompanyInfo::find().METLegalEntityType;

        InventDim                       inventDim, inventDimDefaultSetting;
        InventTransferLine              transferLine;
        InventItemSalesSetup            inventItemSalesSetup;
        METInventTransferLine           metTransferLine;
        UnitOfMeasureFromRecId          fromUnit, toUnit;

        while select transferLine
            where transferLine.TransferId == _transferId
            join metTransferLine where metTransferLine.InventTransferLine == transferLine.RecId
            join inventDim where inventDim.inventDimId == transferLine.InventDimId
            join METSalesUnit from inventItemSalesSetup
            join inventDimDefaultSetting where inventDimDefaultSetting.inventDimId == inventItemSalesSetup.InventDimId
            && inventItemSalesSetup.ItemId == transferLine.ItemId
            && inventDimDefaultSetting.InventSiteId == inventDim.InventSiteId
        {
            filterCode = metTransferLine.WarehouseCategory;

            // 1. KEG HANDLING — must skip all further logic
            if (legalEntityType == METLegalEntityType::Liquor
                && metTransferLine.IsKegItem)
            {
                headerTmp.KegCount += transferLine.QtyShipped;
                continue;   //  Skip case/broken-case logic
            }

            // 2. Determine Sales Order Unit (case unit)
            METSalesUnit salesOrderUnit = inventItemSalesSetup.METSalesUnit;

            // 3. If TO line UOM = Sales Order Unit → full cases, no broken cases
            if (transferLine.UnitId == salesOrderUnit)
            {
                cases = transferLine.QtyShipped;
                brokenCases = 0;
            }
            else
            {
                // 4. Get conversion factor (Inventory UOM → Sales Order Unit)
                fromUnit = EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(salesOrderUnit);
                toUnit = EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(transferLine.UnitId);

                factor = EcoResProductUnitConverter::convertForReleasedProduct(
                        transferLine.ItemId,
                        transferLine.inventDimId,
                        1,
                        fromUnit,
                        toUnit,
                        NoYes::No,
                        NoYes::No);

                // 5. Calculate full cases
                cases = this.getCases(factor, transferLine.QtyShipped);

                // 6. Calculate broken cases
                brokenCases = transferLine.QtyShipped - (cases * factor);
            }

            // 7. Weight calculation
            shippedWeight = metTransferLine.TOUnitWeight * transferLine.QtyShipped;

            // Consolidate WEIGHT
            existingWeight = consolidatedWeightMap.exists(filterCode)
            ? consolidatedWeightMap.lookup(filterCode)
            : 0;

            consolidatedWeightMap.insert(filterCode, existingWeight + shippedWeight);

            // Consolidate CASES
            existingCases = consolidatedCasesMap.exists(filterCode)
            ? consolidatedCasesMap.lookup(filterCode)
            : 0;

            consolidatedCasesMap.insert(filterCode, existingCases + cases);

            // Consolidate BROKEN CASES
            existingBrokenCases = consolidatedBrokenCasesMap.exists(filterCode)
            ? consolidatedBrokenCasesMap.lookup(filterCode)
            : 0;

            consolidatedBrokenCasesMap.insert(filterCode, existingBrokenCases + brokenCases);
        }
    }

    /// <summary>
    /// Add product types for the sales order.
    /// </summary>
    /// <param name = "_transferId">Transfer order number</param>
    /// <param name = "_shipmentId">Shipment number</param>
    public void getProductTypesDetailsSO(InventTransferId _salesId, MetShipmentId _shipmentId)
    {
        Factor                          factor;
        METCase                         cases,          existingCases,          totalCases;
        InventQty                       deliveryNoteQty;
        METUnitWeight                   shippedWeight,  existingWeight,         totalWeight;
        METUnitWeight                   productWeight,  existingProductWeight,  totalProductWeight;
        METBrokenCase                   brokenCases,    existingBrokenCases,    totalBrokenCases;
        METItemTypes                    itemType;
        METLegalEntityType              legalEntityType = CompanyInfo::find().METLegalEntityType;
        UnitOfMeasureFromRecId          fromUnit,toUnit;

        InventDim                       inventDim, inventDimDefaultSetting;
        SalesLine                       salesLine;
        METSalesLine                    metSalesLine;
        InventItemSalesSetup            inventItemSalesSetup;
        WMSOrderTrans                   wmsOrderTrans;
        UnitOfMeasureSymbol             shippedUnitId;
        CustPackingSlipTrans            custPackingSlipTrans;
        METInventItemOrderSetup         metInventItemOrderSetup;
        METSalesOrderShipmentLoadLines  shipmentLines;
        boolean                         containsE;
        boolean                         isKeg;

        while select salesLine where salesLine.SalesId == _salesId
        join SalesUnitWeight, Indicators, IsKegItem from metSalesLine where metSalesLine.SalesLine == salesLine.RecId
        join inventDim where inventDim.inventDimId == salesLine.InventDimId
        join PickedQty, Quantity, CWQuantity from shipmentLines where shipmentLines.ShipmentId == _shipmentId //Bug 351253 Added ShipmentId filter to prevent picking shipment lines from other shipments
            &&  shipmentLines.OrderNum == salesLine.SalesId
            && shipmentLines.LineNum == salesLine.LineNum
            && shipmentLines.ShipmentId == _shipmentId
        join wmsOrderTrans
            where wmsOrderTrans.RecId == shipmentLines.WMSOrderTransRecId
        join ItemType from metInventItemOrderSetup where metInventItemOrderSetup.ItemId == salesLine.ItemId
            && metInventItemOrderSetup.SiteId == inventDim.InventSiteId
        {
            // Reset per-line values
            cases           = 0;
            brokenCases     = 0;

            // Delivery note qty expressed in sales (case) unit
            deliveryNoteQty = wmsOrderTrans.METPickedCases;

            if (PdsGlobal::pdsIsCWItem(salesLine.ItemId)) // for catch weight item
            {
                deliveryNoteQty = shipmentLines.CWQuantity;
            }

            itemType        = metInventItemOrderSetup.ItemType;
            shippedWeight   = metSalesLine.SalesUnitWeight * deliveryNoteQty;
            productWeight   = metSalesLine.SalesUnitWeight;

            // Determine indicators and keg status
            containsE   = (metSalesLine.Indicators && strScan(metSalesLine.Indicators, 'E', 1, strLen(metSalesLine.Indicators)));
            isKeg       = (metSalesLine.IsKegItem == NoYes::Yes);

            // Cases: only when line does NOT contain 'E' AND IsKegItem = No
            if (!containsE && !isKeg)
            {
                // Calculate cases from the picked quantity
                //cases = this.getCases(factor, shipmentLines.PickedQty);
                // Changed to Quantity (already in sales/case unit) as PickedQty is in inventory unit (e.g. KG for weight-based items) causing incorrect case count
                cases = any2Int(RoundUp(deliveryNoteQty, 1));
            }

            // Broken cases: when line contains 'E' indicator — use delivery note qty
            // Consolidate broken cases according to delivery note quantity (rounded similarly to getCases)
            brokenCases += wmsOrderTrans.METPickedBrokenCases;

            // Keg handling: preserve behaviour for header keg count (use METSalesLine.IsKegItem)
            if (legalEntityType == METLegalEntityType::Liquor && isKeg)
            {
                headerTmp.KegCount += deliveryNoteQty;
            }

            //Weight
            if (consolidatedWeightMap.exists(itemType))
            {
                existingWeight = consolidatedWeightMap.lookup(itemType);
                consolidatedWeightMap.insert(itemType, existingWeight + shippedWeight);
            }
            else
            {
                consolidatedWeightMap.insert(itemType, shippedWeight);
            }

            // Cases (only non-E and non-keg lines contribute)
            if (cases)
            {
                if (consolidatedCasesMap.exists(itemType))
                {
                    existingCases = consolidatedCasesMap.lookup(itemType);
                    consolidatedCasesMap.insert(itemType, existingCases + cases);
                }
                else
                {
                    consolidatedCasesMap.insert(itemType, cases);
                }
            }

            // Broken cases (only lines with 'E' contribute)
            if (brokenCases)
            {
                if (consolidatedBrokenCasesMap.exists(itemType))
                {
                    existingBrokenCases = consolidatedBrokenCasesMap.lookup(itemType);
                    consolidatedBrokenCasesMap.insert(itemType, existingBrokenCases + brokenCases);
                }
                else
                {
                    consolidatedBrokenCasesMap.insert(itemType, brokenCases);
                }
            }
        }
    }

    /// <summary>
    /// Get customer details
    /// </summary>
    /// <param name = "_custAccount">Customer account number</param>
    /// <param name = "_inventLocationId">Shipment warehouse</param> //Added for Task 428926 <HS>
    /// <remarks>
    /// Task 428926: Warehouse/Customer instruction is taken from the first active instruction
    /// for the customer + warehouse combination of the shipment.
    /// Active = StartDate on or before today and EndDate blank or on/after today.
    /// </remarks>
    public void addCustomerDetails(AccountNum _custAccount, InventLocationId _inventLocationId)
    {
        CustTable                       custTable = CustTable::find(_custAccount);
        DirPartyLocation                dirPartyLocation;
        LogisticsElectronicAddress      logisticsElectronicAddress;

        METWarehouseCarrierCustomer     whsCarrierCustomer;
        METWarehouseCarrier             whsCarrier;
        TransDate                       today = DateTimeUtil::getSystemDate(DateTimeUtil::getCompanyTimeZone());

        // select firstonly CustomerInstruction, WarehouseInstruction from whsCustomerCarrier
        //    where whsCustomerCarrier.CustAccount == _custAccount;
        if (_custAccount && _inventLocationId)
        {
            select firstonly whsCarrierCustomer
                order by RecId asc
                where whsCarrierCustomer.CustAccount == _custAccount
                exists join whsCarrier
                    where whsCarrier.WarehouseCarierId  == whsCarrierCustomer.WarehouseCarierId
                       && whsCarrier.InventLocationId   == _inventLocationId
                       && whsCarrier.StartDate          <= today
                       && (whsCarrier.EndDate == dateNull() || whsCarrier.EndDate >= today);
        }

        headerTmp.WareHouseInstruction  = whsCarrierCustomer.WarehouseInstruction;
        headerTmp.CustomerInstruction   = whsCarrierCustomer.CustomerInstruction;

        select firstonly Locator from  logisticsElectronicAddress
            exists join dirPartyLocation
             where logisticsElectronicAddress.location == dirPartyLocation.Location
            && dirPartyLocation.Party == custTable.Party
            && logisticsElectronicAddress.type == LogisticsElectronicAddressMethodType::Phone
            && logisticsElectronicAddress.IsPrimary == NoYes::Yes;

        headerTmp.CustomerAccountNumber = custTable.AccountNum;
        headerTmp.CustomerName          = custTable.name();
        headerTmp.CustomerAddress       = custTable.address();
        headerTmp.CustomerPhone         = logisticsElectronicAddress.Locator;
    }

    /// <summary>
    /// Get the container table and insert into header tmp table.
    /// </summary>
    /// <param name = "_shipmentId"></param>
    public void addContainerTable(MetShipmentId _shipmentId)
    {
        MetContainerTable               containerTable;
        METContainerTypeTable           containerTypeTable;
        METSalesOrderShipmentLoadHeader shipmentHeader = METSalesOrderShipmentLoadHeader::findByShipmentId(_shipmentId);

        while select containerTable
            where containerTable.ShipmentId == _shipmentId
            join containerTypeTable
                where containerTypeTable.ContainerTypeCode == containerTable.ContainerTypeCode
                && containerTypeTable.InventLocationId == shipmentHeader.Warehouse
        {
            if (containerTable.ContainerTypeCode == containerTypeCodeSEC)
            {
                headerTmp.SecurityCartons += containerTable.ContainerQty;
            }
            else if (containerTable.ContainerTypeCode == containerTypeCodeREP)
            {
                headerTmp.RepackCartons += containerTable.ContainerQty;
            }
            else if (containerTable.ContainerTypeCode == containerTypeCodeCHP)
            {
                headerTmp.ChepPalletCount += containerTable.ContainerQty;
            }
            else if (containerTable.ContainerTypeCode == containerTypeCodeLOS)
            {
                headerTmp.LoscamPalletCount += containerTable.ContainerQty;
            }
            else if (containerTable.ContainerTypeCode == containerTypeCodeLFT)
            {
                headerTmp.PalletLiftCount += containerTable.ContainerQty;
            }
            else if (containerTable.ContainerTypeCode == containerTypeCodeBLT)
            {
                headerTmp.CoolerBlanketCount += containerTable.ContainerQty;
            }
            else if (containerTable.ContainerTypeCode == containerTypeCodePLN)
            {
                headerTmp.PlainPalletCount += containerTable.ContainerQty;
            }
            else if (containerTable.ContainerTypeCode == containerTypeCodeTOT)
            {
                headerTmp.ToteCount += containerTable.ContainerQty;
            }
        }
    }

    /// <summary>
    /// Get the pallet & container weight total
    /// </summary>
    /// <param name = "_shipmentId">Shipment id</param>
    /// <param name = "_fromWhs">From warehouse</param>
    /// <param name = "_transactionType">Transaction type</param>
    /// <returns></returns>
    public real palletContainerWeight(MetShipmentId _shipmentId)
    {
        real                            palletContainerWeight   = 0;
        Weight                          containerTypeWeight     = 0;
        MetContainerQty                 containerQty            = 0;
        MetContainerTable               containerTable;
        METContainerTypeTable           containerTypeTable;
        METSalesOrderShipmentLoadHeader shipmentLoadHeader = METSalesOrderShipmentLoadHeader::findByShipmentId(_shipmentId);

        while select containerTable
            where containerTable.ShipmentId == _shipmentId
            join containerTypeTable
                where containerTypeTable.ContainerTypeCode == containerTable.ContainerTypeCode
                && containerTypeTable.InventLocationId == shipmentLoadHeader.Warehouse
        {
            palletContainerWeight += containerTable.ContainerQty * containerTypeTable.Weight;
        }

        processedShipmentIdsSet.add(_shipmentId);

        return palletContainerWeight;
    }

    /// <summary>
    /// Get the case value of each shipped qty on the line.
    /// </summary>
    /// <param name = "_factor">Factor</param>
    /// <param name = "_qtyShipped">Quantity</param>
    /// <returns></returns>
    public METCase getCases(Factor _factor, InventTransferQtyShipped _qtyShipped)
    {
        if (_factor <= 0)
        {
            return 0;
        }

        // Full cases = floor(QtyShipped / EA per case)
        return any2Int(_qtyShipped / _factor);
    }

